class ListUtil {
    static addIfNotPresent(list, addition) {
        if (!!addition && !list.includes(addition)) {
            list.push(addition);
        }
    }
    static addAllIfNotPresent(list, listOfAdditions) {
        for (const xx of listOfAdditions) {
            ListUtil.addIfNotPresent(list, xx);
        }
    }
}

class StudyConfigurationModelStdlib {
    static getInstance() {
        if (this.stdlib === undefined || this.stdlib === null) {
            this.stdlib = new StudyConfigurationModelStdlib();
        }
        return this.stdlib;
    }
    constructor() {
        this.elements = [];
        this.elements.push(PatientVisitStatus.completed);
        this.elements.push(PatientVisitStatus.missed);
        this.elements.push(PatientVisitStatus.canceled);
        this.elements.push(Month.January);
        this.elements.push(Month.February);
        this.elements.push(Month.March);
        this.elements.push(Month.April);
        this.elements.push(Month.May);
        this.elements.push(Month.June);
        this.elements.push(Month.July);
        this.elements.push(Month.August);
        this.elements.push(Month.September);
        this.elements.push(Month.October);
        this.elements.push(Month.November);
        this.elements.push(Month.December);
        this.elements.push(TimeUnit.hours);
        this.elements.push(TimeUnit.days);
        this.elements.push(TimeUnit.weeks);
        this.elements.push(TimeUnit.months);
        this.elements.push(PhaseState.completed);
        this.elements.push(PhaseState.started);
        this.elements.push(PhaseState.skipped);
        this.elements.push(EventState.completed);
        this.elements.push(EventState.eachCompleted);
        this.elements.push(EventState.started);
        this.elements.push(EventState.scheduled);
        this.elements.push(EventState.skipped);
        this.elements.push(SimpleOperators.plus);
        this.elements.push(SimpleOperators.minus);
        this.elements.push(TypeOfEvent.site);
        this.elements.push(TypeOfEvent.preparation);
        this.elements.push(TypeOfEvent.video);
        this.elements.push(TypeOfEvent.phone);
        this.elements.push(TypeOfEvent.other);
        for (const lib of freonConfiguration.customStdLibs) {
            ListUtil.addAllIfNotPresent(this.elements, lib.elements);
        }
    }
    find(name, metatype) {
        if (!!name) {
            const possibles = this.elements.filter((elem) => elem.name === name);
            if (possibles.length !== 0) {
                if (metatype) {
                    for (const elem of possibles) {
                        if (FreLanguage.getInstance().metaConformsToType(elem, metatype)) {
                            return elem;
                        }
                    }
                }
                else {
                    return possibles[0];
                }
            }
        }
        return null;
    }
}

