class StudyConfigurationModelSemanticAnalysisWalker extends StudyConfigurationModelDefaultWorker {
    constructor(changesToBeMade) {
        super();
        this.changesToBeMade = null;
        this.changesToBeMade = changesToBeMade;
    }
    execBeforeTaskReference(modelelement) {
        let referredElem;
        referredElem = modelelement.task;
        if (!!modelelement.task && modelelement.task.referred === null) {
            this.findReplacement(modelelement, referredElem);
        }
        return false;
    }
    execBeforeEventReferenceExpression(modelelement) {
        let referredElem;
        referredElem = modelelement.event;
        if (!!modelelement.event && modelelement.event.referred === null) {
            this.findReplacement(modelelement, referredElem);
        }
        referredElem = modelelement.eventState;
        if (!!modelelement.eventState && modelelement.eventState.referred === null) {
            this.findReplacement(modelelement, referredElem);
        }
        return false;
    }
    execBeforePeriodReferenceExpression(modelelement) {
        let referredElem;
        referredElem = modelelement.period;
        if (!!modelelement.period && modelelement.period.referred === null) {
            this.findReplacement(modelelement, referredElem);
        }
        referredElem = modelelement.periodState;
        if (!!modelelement.periodState && modelelement.periodState.referred === null) {
            this.findReplacement(modelelement, referredElem);
        }
        return false;
    }
    execBeforeCountExpression(modelelement) {
        let referredElem;
        referredElem = modelelement.event;
        if (!!modelelement.event && modelelement.event.referred === null) {
            this.findReplacement(modelelement, referredElem);
        }
        return false;
    }
    findReplacement(modelelement, referredElem) {
        const scoper = FreLanguageEnvironment.getInstance().scoper;
        const possibles = scoper.getVisibleElements(modelelement).filter((elem) => elem.name === referredElem.name);
        if (possibles.length > 0) {
            let replacement = null;
            for (const elem of possibles) {
                const metatype = elem.freLanguageConcept();
                if (FreLanguage.getInstance().metaConformsToType(elem, "Task")) {
                    replacement = TaskReference.create({ task: FreNodeReference.create(referredElem.name, metatype) });
                }
                else if (FreLanguage.getInstance().metaConformsToType(elem, "Event")) {
                    replacement = EventReferenceExpression.create({ event: FreNodeReference.create(referredElem.name, metatype) });
                }
                else if (FreLanguage.getInstance().metaConformsToType(elem, "EventState")) {
                    replacement = EventReferenceExpression.create({
                        eventState: FreNodeReference.create(referredElem.name, metatype),
                    });
                }
                else if (FreLanguage.getInstance().metaConformsToType(elem, "Period")) {
                    replacement = PeriodReferenceExpression.create({
                        period: FreNodeReference.create(referredElem.name, metatype),
                    });
                }
                else if (FreLanguage.getInstance().metaConformsToType(elem, "PhaseState")) {
                    replacement = PeriodReferenceExpression.create({
                        periodState: FreNodeReference.create(referredElem.name, metatype),
                    });
                }
                else if (FreLanguage.getInstance().metaConformsToType(elem, "Event")) {
                    replacement = CountExpression.create({ event: FreNodeReference.create(referredElem.name, metatype) });
                }
                else {
                    throw new Error("Semantic analysis error: cannot replace reference: " + referredElem.name + " of type " + metatype + ".");
                }
            }
            this.changesToBeMade.set(modelelement, replacement);
        }
        else {
            if (referredElem.name === "true") {
                this.changesToBeMade.set(modelelement, Task.create({ showDetails: true }));
            }
            else if (referredElem.name === "false") {
                this.changesToBeMade.set(modelelement, Task.create({ showDetails: false }));
            }
        }
    }
}

class StudyConfigurationModelSemanticAnalyser {
    correct(modelunit) {
        let changesToBeMade = new Map();
        const myWalker = new StudyConfigurationModelWalker();
        let myCorrector = new StudyConfigurationModelSemanticAnalysisWalker(changesToBeMade);
        myWalker.myWorkers.push(myCorrector);
        myWalker.walk(modelunit, () => {
            return true;
        });
        for (const [toBeReplaced, newObject] of changesToBeMade) {
            const myType = FreLanguage.getInstance().concept(toBeReplaced.freLanguageConcept());
            myType.properties.forEach((prop) => {
                if (prop.type !== "boolean" && !!toBeReplaced[prop.name]) {
                    newObject[prop.name] = toBeReplaced[prop.name];
                }
            });
            let parent = toBeReplaced.freOwnerDescriptor().owner;
            const propName = toBeReplaced.freOwnerDescriptor().propertyName;
            const propIndex = toBeReplaced.freOwnerDescriptor().propertyIndex;
            if (propIndex !== undefined) {
                parent[propName].splice(propIndex, 1, newObject);
            }
            else {
                parent[propName] = newObject;
            }
        }
    }
}

