<script>import { LIMITEDRADIO_LOGGER } from "./ComponentLoggers.js";
import { ALT, ARROW_DOWN, ARROW_LEFT, ARROW_RIGHT, ARROW_UP, AST, CONTROL, FreEditor, FreLogger, LimitedControlBox, SHIFT } from "@freon4dsl/core";
import { afterUpdate, onMount } from "svelte";
import { MdRadio } from "@material/web/all.js";
export let box;
export let editor;
const LOGGER = LIMITEDRADIO_LOGGER;
let id = box.id;
let myEnum = box.getPossibleNames();
let currentValue = box.getNames()[0];
let allElements = [];
let ariaLabel = "toBeDone";
let isHorizontal = false;
function findSelectedElement() {
  let selected = null;
  for (let i = 0; i < myEnum.length; i++) {
    if (myEnum[i] === currentValue) {
      selected = allElements[i];
    }
  }
  return selected;
}
async function setFocus() {
  let selected = findSelectedElement();
  if (!!selected) {
    selected.focus();
  }
}
const refresh = (why) => {
  LOGGER.log("REFRESH LimitedControlBox: " + why);
  currentValue = box.getNames()[0];
};
onMount(() => {
  currentValue = box.getNames()[0];
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
afterUpdate(() => {
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
const onChange = (event) => {
  currentValue = event.target["value"];
  AST.change(() => {
    box.setNames([currentValue]);
  });
  editor.selectElementForBox(box);
  event.stopPropagation();
};
const onClick = (event) => {
  event.stopPropagation();
};
const onKeyDown = (event) => {
  if (event.key !== SHIFT && event.key !== CONTROL && event.key !== ALT) {
    switch (event.key) {
      case ARROW_LEFT:
      case ARROW_RIGHT:
      case ARROW_UP:
      case ARROW_DOWN: {
        event.stopPropagation();
        event.preventDefault();
      }
    }
  }
};
</script>

<span role="radiogroup" aria-labelledby={ariaLabel} {id} class="limited-radio-component-group" class:limited-radio-component-vertical={!isHorizontal}>
    {#each myEnum as nn, i}
        <span class="limited-radio-component-single">
            <md-radio
                id="{id}-{nn}-{i}"
                name="{id}-group"
                role="radio"
                tabindex="0"
                aria-checked={currentValue === nn}
                value={nn}
                checked={currentValue === nn}
                aria-label="radio-control-{nn}"
                on:click={onClick}
                on:change={onChange}
                on:keydown={onKeyDown}
                bind:this={allElements[i]}
            ></md-radio>
            <label class="limited-radio-component-label" for="{id}-{nn}-{i}">{nn}</label>
        </span>
    {/each}
</span>
