<script>import { afterUpdate, onMount, tick } from "svelte";
import ErrorTooltip from "./ErrorTooltip.svelte";
import { viewport } from "./svelte-utils/index.js";
import { Box } from "@freon4dsl/core";
export let box;
export let element;
let content;
let top = 10;
let height = 8;
async function calcPos() {
  await tick();
  if (!!element) {
    let elementRect = element.getBoundingClientRect();
    if (!!elementRect) {
      top = elementRect.top - $viewport.top;
    } else {
      console.log("No bounding rect");
    }
  } else {
    console.log("NO element");
  }
}
onMount(() => {
  calcPos();
  content = box.errorMessages;
});
afterUpdate(() => {
  calcPos();
  content = box.errorMessages;
});
function ignore(m) {
  m.stopPropagation();
  m.preventDefault();
}
</script>

<!-- svelte-ignore a11y-click-events-have-key-events -->
<!-- svelte-ignore a11y-no-static-element-interactions -->
<span on:click={ignore} class="error-positioning" style="top: {top}px; height: {height}px;">
    <ErrorTooltip {box} hasErr={true} parentTop={top} parentLeft={2}>
        <span class="error-marker" style="height: {height}px;">&nbsp</span>
    </ErrorTooltip>
</span>
