<!-- This component switches between a <span> and an <input> HTML element. -->
<!-- This means that there is extra functionality to set the caret position -->
<!-- (cursor or selected text), when the switch is being made. -->

<script>import { afterUpdate, beforeUpdate, createEventDispatcher, onMount } from "svelte";
import { componentId, executeCustomKeyboardShortCut, setBoxSizes } from "./svelte-utils/index.js";
import {
  ActionBox,
  ALT,
  ARROW_DOWN,
  ARROW_LEFT,
  ARROW_RIGHT,
  ARROW_UP,
  BACKSPACE,
  CONTROL,
  DELETE,
  ENTER,
  ESCAPE,
  isActionBox,
  isActionTextBox,
  isSelectBox,
  FreCaret,
  FreCaretPosition,
  FreEditor,
  FreLogger,
  SelectBox,
  FreErrorSeverity,
  SHIFT,
  TAB,
  ItemGroupBox,
  Box,
  isRegExp,
  triggerTypeToString
} from "@freon4dsl/core";
import { CharAllowed } from "@freon4dsl/core";
import RenderComponent from "./RenderComponent.svelte";
import { runInAction } from "mobx";
import { replaceHTML } from "./svelte-utils/index.js";
import { Button } from "flowbite-svelte";
import { FontAwesomeIcon } from "@fortawesome/svelte-fontawesome";
import {
  faGripVertical,
  faEllipsis,
  faXmark,
  faCaretRight,
  faCaretDown,
  faShareNodes,
  faSquareArrowUpRight,
  faLinkSlash,
  faAnglesDown
} from "@fortawesome/free-solid-svg-icons";
const LOGGER = new FreLogger("ItemGroupComponent");
const dispatcher = createEventDispatcher();
export let box;
export let editor;
export let isEditing = false;
export let partOfActionBox = false;
export let text;
let id;
id = !!box ? componentId(box) : "texitemgroup-with-unknown-box";
let spanElement;
let inputElement;
let placeholder = "<..>";
let originalText;
let editStart = false;
let from = -1;
let to = -1;
let cssClass = "";
let style;
let contentElement = null;
let label;
let child;
let isExpanded = false;
let contentStyle = "display: none";
let isDraggable = true;
let canShare = false;
let canDelete = false;
let canUnlink = false;
let canCRUD = false;
let isRequired = false;
let canEdit = true;
let canExpand = true;
let canDuplicate = false;
let placeHolderStyle;
$: placeHolderStyle = partOfActionBox ? "text-component-action-placeholder" : "text-component-placeholder";
let boxType = "text";
$: boxType = !!box.parent ? isActionBox(box?.parent) ? "action" : isSelectBox(box?.parent) ? "select" : "text" : "text";
onMount(() => {
  if (!!box) {
    originalText = text = box.getText();
    placeholder = box.placeHolder;
    isExpanded = box.isExpanded;
    canShare = box.canShare;
    canCRUD = box.canCRUD;
    canDelete = box.canDelete;
    canUnlink = box.canUnlink;
    canEdit = box.canEdit;
    isRequired = box.isRequired;
    contentStyle = isExpanded ? "display:block;" : "display:none;";
    canDuplicate = box.canDuplicate;
    setInputWidth();
    box.setFocus = setFocus;
    box.setCaret = setCaret;
    box.refreshComponent = refresh;
  }
});
export async function setFocus() {
  if (!!inputElement) {
    inputElement.focus();
    inputElement.select();
  } else {
    isEditing = true;
    editStart = true;
    originalText = text;
    setCaret(editor.selectedCaretPosition);
  }
}
function setFromAndTo(inFrom, inTo) {
  if (inFrom < inTo) {
    from = inFrom;
    to = inTo;
  } else {
    from = inTo;
    to = inFrom;
  }
}
const setCaret = (freCaret) => {
  switch (freCaret.position) {
    case FreCaretPosition.RIGHT_MOST:
      from = to = text.length;
      break;
    case FreCaretPosition.LEFT_MOST:
    case FreCaretPosition.UNSPECIFIED:
      from = to = 0;
      break;
    case FreCaretPosition.INDEX:
      setFromAndTo(freCaret.from, freCaret.to);
      break;
    default:
      from = to = 0;
      break;
  }
  if (isEditing && !!inputElement) {
    inputElement.selectionStart = from >= 0 ? from : 0;
    inputElement.selectionEnd = to >= 0 ? to : 0;
    inputElement.focus();
  }
};
function startEditing(event) {
  if (canEdit) {
    LOGGER.log("startEditing " + id);
    editor.selectElementForBox(box);
    isEditing = true;
    editStart = true;
    originalText = text;
    let { anchorOffset, focusOffset } = document.getSelection();
    setFromAndTo(anchorOffset, focusOffset);
  }
  event.preventDefault();
  event.stopPropagation();
  if (canEdit) {
    dispatcher("startEditing", { content: text, caret: from });
  }
}
function onClick(event) {
  if (!!inputElement) {
    setFromAndTo(inputElement.selectionStart, inputElement.selectionEnd);
  }
  if (partOfActionBox) {
    dispatcher("textUpdate", { content: text, caret: from });
  }
  event.stopPropagation();
}
function endEditing() {
  LOGGER.log(" endEditing " + id);
  if (isEditing) {
    isEditing = false;
    from = -1;
    to = -1;
    if (!partOfActionBox) {
      runInAction(() => {
        if (box.deleteWhenEmpty && text.length === 0) {
          editor.deleteBox(box);
        } else if (text !== box.getText()) {
          LOGGER.log(`   text is new value`);
          box.setText(text);
        }
      });
    } else {
      dispatcher("endEditing");
    }
  }
}
function getCaretPosition(event) {
  const target = event.target;
  setFromAndTo(target.selectionStart, target.selectionEnd);
}
const onKeyDown = (event) => {
  if (event.altKey || event.ctrlKey) {
    executeCustomKeyboardShortCut(event, 0, box, editor);
    if (event.ctrlKey && !event.altKey && event.key === "z") {
    } else if (event.ctrlKey && event.altKey && event.key === "z" || !event.ctrlKey && event.altKey && event.key === BACKSPACE) {
    } else if (event.ctrlKey && !event.altKey && event.key === "h") {
      event.stopPropagation();
    } else if (event.ctrlKey && !event.altKey && event.key === "x") {
      event.stopPropagation();
    } else if (event.ctrlKey && !event.altKey && event.key === "c") {
      event.stopPropagation();
      navigator.clipboard.writeText(text).then(() => {
        editor.setUserMessage("Text copied to clipboard", FreErrorSeverity.Info);
      }).catch((err) => {
        editor.setUserMessage("Error in copying text: " + err.message);
      });
    } else if (event.ctrlKey && !event.altKey && event.key === "v") {
      event.stopPropagation();
      event.preventDefault();
    } else if (event.key === SHIFT || event.key === CONTROL || event.key === ALT) {
      LOGGER.log("SHIFT: stop propagation");
      event.stopPropagation();
    }
  } else {
    switch (event.key) {
      case ARROW_DOWN:
      case ARROW_UP:
      case ENTER:
      case ESCAPE:
      case TAB: {
        LOGGER.log("Arrow up, arrow down, enter, escape, or tab pressed: " + event.key);
        break;
      }
      case ARROW_LEFT: {
        getCaretPosition(event);
        LOGGER.log("Arrow-left: Caret at: " + from);
        if (from !== 0) {
          event.stopPropagation();
          LOGGER.log("dispatching from arrow-left");
          dispatcher("textUpdate", { content: text, caret: from - 1 });
        } else {
          endEditing();
        }
        break;
      }
      case ARROW_RIGHT: {
        getCaretPosition(event);
        LOGGER.log("Arrow-right: Caret at: " + from);
        if (from !== text.length) {
          event.stopPropagation();
          LOGGER.log("dispatching from arrow-right");
          dispatcher("textUpdate", { content: text, caret: from + 1 });
        } else {
          endEditing();
        }
        break;
      }
      case BACKSPACE: {
        if (!event.ctrlKey && event.altKey && !event.shiftKey) {
        } else if (!event.ctrlKey && event.altKey && event.shiftKey) {
        } else {
          getCaretPosition(event);
          LOGGER.log("Caret at: " + from);
          if (from !== 0) {
            event.stopPropagation();
          } else if (text === "" || !!text) {
            if (box.deleteWhenEmptyAndErase) {
              editor.deleteBox(box);
              event.stopPropagation();
              return;
            }
            editor.selectPreviousLeaf();
          } else {
            endEditing();
            editor.selectPreviousLeaf();
          }
        }
        break;
      }
      case DELETE: {
        if (!event.ctrlKey && !event.altKey && event.shiftKey) {
        } else {
          event.stopPropagation();
          getCaretPosition(event);
          if (to !== text.length) {
            event.stopPropagation();
          } else if (text === "" || !text) {
            if (box.deleteWhenEmptyAndErase) {
              editor.deleteBox(box);
              return;
            } else {
              endEditing();
              editor.selectNextLeaf();
            }
          }
        }
        break;
      }
      default: {
        getCaretPosition(event);
        switch (box.isCharAllowed(text, event.key, from)) {
          case CharAllowed.OK:
            event.stopPropagation();
            if (editor.selectedBox.kind === "ActionBox") {
              const matchingOption = editor.selectedBox.getOptions(editor).find((option) => {
                if (isRegExp(option.action.trigger)) {
                  if (option.action.trigger.test(event.key)) {
                    LOGGER.log("Matching regexp" + triggerTypeToString(option.action.trigger));
                    return true;
                  }
                  return false;
                }
              });
              if (!!matchingOption) {
                let execresult = null;
                runInAction(() => {
                  runInAction(() => {
                    const command = matchingOption.action.command();
                    execresult = command.execute(box, event.key, editor, 0);
                  });
                  if (!!execresult) {
                    execresult();
                  }
                });
                event.preventDefault();
                event.stopPropagation();
              }
            } else {
            }
            break;
          case CharAllowed.NOT_OK:
            LOGGER.log("KeyPressAction.NOT_OK");
            event.preventDefault();
            event.stopPropagation();
            break;
          case CharAllowed.GOTO_NEXT:
            LOGGER.log("KeyPressAction.GOTO_NEXT");
            if (from === 0) {
              editor.selectNextLeaf();
            } else if (to === text.length) {
              editor.selectPreviousLeaf();
            } else {
            }
            LOGGER.log("    NEXT LEAF IS " + editor.selectedBox.role);
            if (isActionTextBox(editor.selectedBox)) {
              LOGGER.log("     is an action box");
              editor.selectedBox.parent.triggerKeyPressEvent(event.key);
            } else {
              LOGGER.log("     is NOT an action box");
            }
            event.preventDefault();
            event.stopPropagation();
            break;
        }
      }
    }
  }
};
const onFocusOut = (e) => {
  if (!partOfActionBox && isEditing) {
    endEditing();
  } else {
    dispatcher("onFocusOutText");
  }
};
const refresh = () => {
  placeholder = box.placeHolder;
  if (!isEditing) {
    text = box.getText();
    canShare = box.canShare;
    canCRUD = box.canCRUD;
    canDelete = box.canDelete;
    canUnlink = box.canUnlink;
    canEdit = box.canEdit;
    canDuplicate = box.canDuplicate;
  }
  boxType = box.parent instanceof ActionBox ? "action" : box.parent instanceof SelectBox ? "select" : "text";
  setInputWidth();
  cssClass = box.cssClass;
  label = box.getLabel();
  child = box?.child;
};
beforeUpdate(() => {
  if (editStart && !!inputElement) {
    setInputWidth();
    inputElement.focus();
    editStart = false;
  }
});
afterUpdate(() => {
  if (editStart && !!inputElement) {
    inputElement.selectionStart = from >= 0 ? from : 0;
    inputElement.selectionEnd = to >= 0 ? to : 0;
    setInputWidth();
    inputElement.focus();
    editStart = false;
  }
  if (isEditing && partOfActionBox) {
    if (text !== originalText) {
      dispatcher("textUpdate", { content: text, caret: from + 1 });
    }
  }
  setInputWidth();
  placeholder = box.placeHolder;
  box.setFocus = setFocus;
  box.setCaret = setCaret;
  box.refreshComponent = refresh;
});
function setInputWidth() {
  if (!!widthSpan && !!inputElement) {
    let value = inputElement.value;
    if (value !== void 0 && value !== null && value.length === 0) {
      value = placeholder;
      if (placeholder.length === 0) {
        value = " ";
      }
    }
    widthSpan.innerHTML = replaceHTML(value);
    const width = widthSpan.offsetWidth + 2 + "px";
    inputElement.style.width = width;
  }
}
function onDragStart(event) {
  event.stopPropagation();
  event.preventDefault();
}
let widthSpan;
function onInput(event) {
  setInputWidth();
}
refresh();
const selectItem = (event) => {
  editor.selectElementForBox(box);
  event.preventDefault();
  event.stopPropagation();
};
function toggleExpanded() {
  contentElement.style.display = contentElement.style.display === "block" ? "none" : "block";
  isExpanded = !isExpanded;
  contentStyle = isExpanded ? "display:block;" : "display:none;";
}
function shareItem() {
  box.executeAction(editor, "make-shareable");
}
function deleteItem() {
  box.executeAction(editor, "delete");
}
function duplicateItem() {
  box.executeAction(editor, "duplicate");
}
</script>

<!-- todo there is a double selection here: two borders are showing -->
<!-- svelte-ignore a11y-no-noninteractive-element-interactions a11y-click-events-have-key-events a11y-interactive-supports-focus -->
<div id="{id}-group" class="item-group {cssClass} w-full" {style} on:click={selectItem} role="button">
    {#key isDraggable}
        <FontAwesomeIcon class="w-3 h-3 ml-1 drag-button" style="cursor: grab;" icon={faGripVertical} />
    {/key}
    {#key isExpanded}
        {#if canExpand}
            <Button pill={true} class="w-4 h-4 p-0 ml-1 toggle-button" color="none" size="xs" on:click={toggleExpanded}>
                <FontAwesomeIcon class="w-3 h-3" icon={isExpanded ? faCaretDown : faCaretRight} />
            </Button>
        {:else}
            <span class="w-5" />
        {/if}
    {/key}
    <span class="item-group-label">{label}</span>
    <span {id} on:click={onClick} role="none">
        {#if isEditing}
            <span {id}>
                <input
                    type="text"
                    class="text-component-input"
                    id="{id}-input"
                    bind:this={inputElement}
                    on:input={onInput}
                    bind:value={text}
                    on:focusout={onFocusOut}
                    on:keydown={onKeyDown}
                    draggable="true"
                    on:dragstart={onDragStart}
                    {placeholder}
                />
                <span class="text-component-width" bind:this={widthSpan}></span>
            </span>
        {:else}
            <!-- contenteditable must be true, otherwise there is no cursor position in the span after a click,
				But ... this is only a problem when this component is inside a draggable element (like List or table)
			-->
            <!-- svelte-ignore a11y-no-noninteractive-element-interactions a11y-click-events-have-key-events -->
            <span
                class="{box.role} text-box-{boxType} text-component-text"
                on:click={startEditing}
                bind:this={spanElement}
                contenteditable="true"
                spellcheck="false"
                id="{id}-span"
                role="none"
            >
                {#if !!text && text.length > 0}
                    {text}{#if canUnlink}<FontAwesomeIcon class="w-3 h-3" icon={faSquareArrowUpRight} />{/if}
                {:else}
                    <span class="{placeHolderStyle} {isRequired ? 'required' : ''}">{placeholder}</span>
                {/if}
            </span>
        {/if}
    </span>
    {#if canCRUD}
        <Button pill={true} size="xs" class="w-7 h-7 p-0 action-button" outline>
            <FontAwesomeIcon class="w-3 h-3" icon={faEllipsis} />
        </Button>
    {/if}
    {#if canShare}
        <Button pill={true} size="xs" class="w-7 h-7 p-0 action-button" outline on:click={shareItem}>
            <FontAwesomeIcon class="w-3 h-3" icon={faShareNodes} />
        </Button>
    {/if}
    {#if canUnlink}
        <Button pill={true} size="xs" class="w-7 h-7 p-0 action-button" outline on:click={shareItem}>
            <FontAwesomeIcon class="w-3 h-3" icon={faLinkSlash} />
        </Button>
    {/if}
    {#if canDuplicate}
        <Button pill={true} size="xs" class="w-7 h-7 p-0 action-button" outline on:click={duplicateItem}>
            <FontAwesomeIcon class="w-3 h-3" icon={faAnglesDown} />
        </Button>
    {/if}
    {#if canDelete}
        <Button pill={true} size="xs" class="w-7 h-7 p-0 action-button" outline on:click={deleteItem}>
            <FontAwesomeIcon class="w-3 h-3" icon={faXmark} />
        </Button>
    {/if}
</div>
{#key contentStyle}
    <div bind:this={contentElement} style={contentStyle}>
        <RenderComponent box={child} {editor} />
    </div>
{/key}
