<script>import "@material/web/slider/slider.js";
import { NUMERICSLIDER_LOGGER } from "./ComponentLoggers.js";
import { MdSlider } from "@material/web/slider/slider.js";
import { FreEditor, NumberControlBox } from "@freon4dsl/core";
import { afterUpdate, onMount } from "svelte";
const LOGGER = NUMERICSLIDER_LOGGER;
export let editor;
export let box;
let id = box.id;
let value = box.getNumber();
let min = box.displayInfo.min;
let max = box.displayInfo.max;
let step = box.displayInfo.step;
let showMarks = box.displayInfo.showMarks;
let sliderElement;
const onChange = (event) => {
  LOGGER.log("NumericSliderComponent.onChange for box " + box.role + ", value:" + sliderElement.value);
  value = sliderElement.value !== null && sliderElement.value !== void 0 ? sliderElement.value : 0;
  box.setNumber(value);
  if (box.selectable) {
    editor.selectElementForBox(box);
  }
  event.stopPropagation();
};
async function setFocus() {
  sliderElement.focus();
}
const refresh = (why) => {
  LOGGER.log("REFRESH NumberControlBox: " + why);
  value = box.getNumber();
};
onMount(() => {
  value = box.getNumber();
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
afterUpdate(() => {
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
const dragStart = (event) => {
  event.preventDefault();
};
</script>

<span class="numeric-slider-component" {id}>
    <md-slider
        labeled
        ticks={showMarks}
        {min}
        {max}
        {step}
        {value}
        draggable={true}
        on:dragstart={dragStart}
        role="slider"
        aria-valuenow={value}
        tabindex={0}
        on:change={onChange}
        bind:this={sliderElement}
    >
    </md-slider>
</span>
