<svelte:options immutable={true} />

<script>import { INDENT_LOGGER } from "./ComponentLoggers.js";
import { Box } from "@freon4dsl/core";
import { afterUpdate, onMount } from "svelte";
import RenderComponent from "./RenderComponent.svelte";
import { componentId } from "./svelte-utils/index.js";
export let box;
export let editor;
const LOGGER = INDENT_LOGGER;
const indentWidth = 8;
let style = `margin-left: ${box?.indent * indentWidth}px;`;
let id = !!box ? componentId(box) : "indent-for-unknown-box";
let cssClass = "";
let child;
onMount(() => {
  box.refreshComponent = refresh;
});
afterUpdate(() => {
  box.refreshComponent = refresh;
});
const refresh = (why) => {
  if (!!box) {
    LOGGER.log("REFRESH Indent for box (" + why + ") " + box?.role + " child " + box?.child?.role);
    child = box?.child;
    style = `margin-left: ${box?.indent * indentWidth}px;`;
    cssClass = box.cssClass;
  }
};
$: {
  refresh(box?.$id);
}
</script>

<span {id} class="indent-component {cssClass}" {style}>
    <RenderComponent box={child} {editor} />
</span>
