<script>import { FREON_LOGGER } from "./ComponentLoggers.js";
import {
  FreEditor,
  FreLogger,
  Box,
  ARROW_UP,
  ARROW_DOWN,
  TAB,
  BACKSPACE,
  ARROW_LEFT,
  DELETE,
  ENTER,
  ARROW_RIGHT,
  isNullOrUndefined,
  isTableRowBox,
  isElementBox,
  AstActionExecutor
} from "@freon4dsl/core";
import RenderComponent from "./RenderComponent.svelte";
import ContextMenu from "./ContextMenu.svelte";
import { afterUpdate, onMount, tick } from "svelte";
import { contextMenu, contextMenuVisible, selectedBoxes, viewport, componentId, shouldBeHandledByBrowser } from "./svelte-utils/index.js";
let LOGGER = FREON_LOGGER;
export let editor;
let element;
let rootBox;
let id;
id = !!rootBox ? componentId(rootBox) : "freon-component-with-unknown-box";
function stopEvent(event) {
  event.preventDefault();
  event.stopPropagation();
  shouldBeHandledByBrowser.set(false);
}
const onKeyDown = (event) => {
  LOGGER.log("FreonComponent onKeyDown: " + event.key + " ctrl: " + event.ctrlKey + " alt: " + event.altKey + " shift: " + event.shiftKey);
  if (event.ctrlKey) {
    if (!event.altKey) {
      switch (event.key) {
        case ARROW_UP:
          editor.selectParent();
          stopEvent(event);
          break;
        case ARROW_DOWN:
          editor.selectFirstLeafChildBox();
          stopEvent(event);
          break;
        case "z":
          if (!$shouldBeHandledByBrowser) {
            console.log("Ctrl-z: UNDO");
            AstActionExecutor.getInstance(editor).undo();
            stopEvent(event);
          }
          break;
        case "y":
          if (!$shouldBeHandledByBrowser) {
            console.log("Ctrl-y: REDO");
            AstActionExecutor.getInstance(editor).redo();
            stopEvent(event);
          }
          break;
        case "x":
          if (!$shouldBeHandledByBrowser) {
            console.log("Ctrl-x: CUT");
            AstActionExecutor.getInstance(editor).cut();
            stopEvent(event);
          }
          break;
        case "c":
          if (!$shouldBeHandledByBrowser) {
            console.log("Ctrl-c: COPY");
            AstActionExecutor.getInstance(editor).copy();
            stopEvent(event);
          }
          break;
        case "v":
          if (!$shouldBeHandledByBrowser) {
            console.log("Ctrl-v: PASTE");
            AstActionExecutor.getInstance(editor).paste();
            stopEvent(event);
          }
          break;
        case "h":
          stopEvent(event);
          break;
        case "a":
          break;
      }
    } else {
      switch (event.key) {
        case "z":
          if (!$shouldBeHandledByBrowser) {
            AstActionExecutor.getInstance(editor).redo();
            stopEvent(event);
          }
          break;
      }
    }
  } else if (event.altKey) {
    if (event.shiftKey) {
      switch (event.key) {
        case BACKSPACE:
          if (!$shouldBeHandledByBrowser) {
            AstActionExecutor.getInstance(editor).redo();
            stopEvent(event);
          }
          break;
      }
    } else {
      switch (event.key) {
        case BACKSPACE:
          if (!$shouldBeHandledByBrowser) {
            AstActionExecutor.getInstance(editor).undo();
            stopEvent(event);
          }
          break;
        case ARROW_UP:
          editor.selectParent();
          stopEvent(event);
          break;
        case ARROW_DOWN:
          editor.selectFirstLeafChildBox();
          stopEvent(event);
          break;
      }
    }
  } else if (event.shiftKey) {
    switch (event.key) {
      case TAB:
        break;
    }
  } else {
    switch (event.key) {
      case ARROW_LEFT:
        editor.selectPreviousLeafIncludingExpressionPreOrPost();
        stopEvent(event);
        break;
      case DELETE:
      case BACKSPACE:
        editor.deleteBox(editor.selectedBox);
        stopEvent(event);
        break;
      case TAB:
      case ENTER:
        break;
      case ARROW_RIGHT:
        editor.selectNextLeafIncludingExpressionPreOrPost();
        stopEvent(event);
        break;
      case ARROW_RIGHT:
        editor.selectNextLeafIncludingExpressionPreOrPost();
        stopEvent(event);
        break;
      case ARROW_DOWN:
        editor.selectBoxBelow(editor.selectedBox);
        stopEvent(event);
        break;
      case ARROW_UP:
        editor.selectBoxAbove(editor.selectedBox);
        stopEvent(event);
        break;
    }
  }
};
function onScroll() {
  $contextMenuVisible = false;
  setTimeout(() => {
    editor.scrollX = element.scrollLeft;
    editor.scrollY = element.scrollTop;
  }, 400);
}
function setViewportSizes(elem) {
  if (!!elem) {
    let rect = elem.getBoundingClientRect();
    if (!!elem.parentElement) {
      let parentRect = elem.parentElement.getBoundingClientRect();
      $viewport.setSizes(rect.height, rect.width, parentRect.top, parentRect.left);
    } else {
      $viewport.setSizes(rect.height, rect.width, 0, 0);
    }
  }
}
onMount(() => {
  setViewportSizes(element);
  const resizeObserver = new ResizeObserver((entries) => {
    $contextMenuVisible = false;
    setTimeout(() => {
      setViewportSizes(entries.at(0).target);
    }, 400);
  });
  resizeObserver.observe(element);
  editor.refreshComponentSelection = refreshSelection;
  editor.refreshComponentRootBox = refreshRootBox;
  return () => resizeObserver.unobserve(element);
});
afterUpdate(() => {
  editor.refreshComponentSelection = refreshSelection;
  editor.refreshComponentRootBox = refreshRootBox;
  setViewportSizes(element);
});
const refreshSelection = async (why) => {
  LOGGER.log("FreonComponent.refreshSelection: " + why + " editor selectedBox is " + editor?.selectedBox?.kind);
  if (!isNullOrUndefined(editor.selectedBox)) {
    await tick();
    $selectedBoxes = getSelectableChildren(editor.selectedBox);
    editor.selectedBox.setFocus();
  }
};
function getSelectableChildren(box) {
  const result = [];
  if (isTableRowBox(box)) {
    for (const child of box.children) {
      result.push(...getSelectableChildren(child));
    }
  } else if (isElementBox(box)) {
    result.push(...getSelectableChildren(box.content));
  } else {
    result.push(box);
  }
  return result;
}
const refreshRootBox = (why) => {
  rootBox = editor.rootBox;
  LOGGER.log(
    "REFRESH " + why + " ==================> FreonComponent with rootbox " + rootBox?.id + " unit " + (!!rootBox?.node ? rootBox.node["name"] : "undefined")
  );
};
refreshRootBox("Initialize FreonComponent");
refreshSelection("Initialize FreonComponent");
</script>

<!-- TODO This makes us dependent on @material/... do we want that?-->
<!-- include the material design styling -->
<svelte:head>
    <link href="https://unpkg.com/material-components-web@latest/dist/material-components-web.min.css" rel="stylesheet" />
    <script src="https://unpkg.com/material-components-web@latest/dist/material-components-web.min.js"></script>
</svelte:head>

<!-- svelte-ignore a11y-no-noninteractive-element-interactions a11y-click-events-have-key-events -->
<div class={"freon-component"} on:keydown={onKeyDown} on:scroll={onScroll} bind:this={element} {id} role="group">
    <div class="gutter"></div>
    <div class="editor-component">
        <RenderComponent {editor} box={rootBox} />
    </div>
</div>
<!-- Here the only instance of ContextMenu is defined -->
<!-- TODO make some default items for the context menu -->
<ContextMenu bind:this={$contextMenu} items={[]} {editor} />
