<script>import { LIMITEDCHECKBOX_LOGGER } from "./ComponentLoggers.js";
import { LimitedControlBox, FreEditor, FreLogger, SHIFT, CONTROL, ALT, SPACEBAR, ARROW_RIGHT, ARROW_LEFT, ARROW_DOWN, ARROW_UP } from "@freon4dsl/core";
import { afterUpdate, onMount } from "svelte";
import { MdCheckbox } from "@material/web/all.js";
export let box;
export let editor;
const LOGGER = LIMITEDCHECKBOX_LOGGER;
let id = box.id;
let currentNames = box.getNames();
let myEnum = box.getPossibleNames();
let allElements = [];
let ariaLabel = "toBeDone";
let isHorizontal = false;
const onClick = (event) => {
  event.stopPropagation();
};
function isChecked(nn) {
  return currentNames.includes(nn);
}
function changed(name) {
  if (isChecked(name)) {
    currentNames.splice(currentNames.indexOf(name), 1);
  } else {
    currentNames.push(name);
  }
  box.setNames(currentNames);
  editor.selectElementForBox(box);
}
async function setFocus() {
  allElements[0].focus();
}
const refresh = (why) => {
  LOGGER.log("REFRESH LimitedControlBox: " + why);
  currentNames = box.getNames();
};
onMount(() => {
  currentNames = box.getNames();
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
afterUpdate(() => {
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
function setFocusToNext() {
  for (let i = 0; i < allElements.length; i++) {
    if (document.activeElement === allElements[i]) {
      if (i === allElements.length - 1) {
        allElements[0].focus();
      } else {
        allElements[i + 1].focus();
      }
      break;
    }
  }
}
function setFocusToPrevious() {
  for (let i = 0; i < allElements.length; i++) {
    if (document.activeElement === allElements[i]) {
      if (i === 0) {
        allElements[allElements.length - 1].focus();
      } else {
        allElements[i - 1].focus();
      }
      break;
    }
  }
}
const onKeyDown = (event) => {
  if (event.key !== SHIFT && event.key !== CONTROL && event.key !== ALT) {
    switch (event.key) {
      case SPACEBAR: {
        event.stopPropagation();
        break;
      }
      case ARROW_RIGHT: {
        if (isHorizontal) {
          setFocusToNext();
          event.stopPropagation();
          event.preventDefault();
        }
        break;
      }
      case ARROW_LEFT: {
        if (isHorizontal) {
          setFocusToPrevious();
          event.stopPropagation();
          event.preventDefault();
        }
        break;
      }
      case ARROW_UP: {
        if (!isHorizontal) {
          setFocusToPrevious();
          event.stopPropagation();
          event.preventDefault();
        }
        break;
      }
      case ARROW_DOWN: {
        if (!isHorizontal) {
          setFocusToNext();
          event.stopPropagation();
          event.preventDefault();
        }
        break;
      }
    }
  }
};
</script>

<span role="group" aria-labelledby={ariaLabel} {id} class="limited-checkbox-component-group" class:limited-checkbox-component-vertical={!isHorizontal}>
    {#each myEnum as nn, i}
        <span class="limited-checkbox-component-single">
            <md-checkbox
                id="{id}-{nn}-{i}"
                value={nn}
                checked={isChecked(nn)}
                aria-label="checkbox-{nn}"
                role="checkbox"
                aria-checked={isChecked(nn)}
                tabindex={0}
                on:change={() => changed(nn)}
                on:click={onClick}
                on:keydown={onKeyDown}
                bind:this={allElements[i]}
            ></md-checkbox>
            <label for="{id}-{nn}-{i}" class="limited-checkbox-component-label">{nn}</label>
        </span>
    {/each}
</span>
