<script>import { DROPDOWN_LOGGER } from "./ComponentLoggers.js";
import { createEventDispatcher } from "svelte";
import { Box, FreLogger } from "@freon4dsl/core";
export let selectedId = "";
export let options = [];
let id = "dropdown";
let cssClass = "";
let style = "";
const dispatcher = createEventDispatcher();
const LOGGER = DROPDOWN_LOGGER;
$: isSelected = (option) => {
  if (options.length === 1) {
    return true;
  }
  return option.id === selectedId;
};
const handleClick = (option) => {
  LOGGER.log("handleClick");
  selectedId = option.id;
  dispatcher("freItemSelected", option);
};
</script>

<span class="dropdown-component-container">
    <nav class="dropdown-component" {id}>
        {#if options.length > 0}
            {#each options as option (option.id + option.label)}
                <!-- svelte-ignore a11y-no-noninteractive-element-interactions a11y-click-events-have-key-events -->
                <div
                    class="dropdown-component-item"
                    class:dropdown-component-selected={isSelected(option)}
                    on:mousedown={(event) => {
                        event.preventDefault();
                        event.stopPropagation();
                        handleClick(option);
                    }}
                    role="none"
                >
                    {option.label}
                </div>
            {/each}
        {:else}
            <div class="dropdown-component-error">No selection available</div>
        {/if}
    </nav>
</span>

<style>
    .dropdown-component-container {
        position: relative;
    }
</style>
