<script>import { SWITCH_LOGGER } from "./ComponentLoggers.js";
import { BooleanControlBox, FreEditor, FreLogger } from "@freon4dsl/core";
import { componentId } from "../index.js";
import { afterUpdate, onMount } from "svelte";
const LOGGER = SWITCH_LOGGER;
export let box;
export let editor;
let id = !!box ? componentId(box) : "switch-for-unknown-box";
let value = box.getBoolean();
let switchElement;
async function setFocus() {
  switchElement.focus();
}
const refresh = (why) => {
  LOGGER.log("REFRESH BooleanControlBox: " + why);
  value = box.getBoolean();
};
onMount(() => {
  value = box.getBoolean();
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
afterUpdate(() => {
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
});
function handleClick(event) {
  const target = event.target;
  value = target.getAttribute("aria-checked") !== "true";
  box.setBoolean(value);
  if (box.selectable) {
    editor.selectElementForBox(box);
  }
  event.stopPropagation();
  LOGGER.log("SwitchComponent.onChange for box " + box.role + ", box value: " + box.getBoolean());
}
</script>

<span class="switch-component">
    <button {id} bind:this={switchElement} role="switch" aria-checked={value} aria-labelledby={`switch-${id}`} on:click={handleClick}> </button>
</span>
