<svelte:options accessors={true} />

<!-- this option lets us set the items props after the component has been created -->

<script>import { CONTEXTMENU_LOGGER } from "./ComponentLoggers.js";
import { calculatePos, clickOutsideConditional } from "./svelte-utils/index.js";
import { tick } from "svelte";
import { FreLogger, MenuItem, FreEditor } from "@freon4dsl/core";
import { contextMenuVisible } from "./svelte-utils/ContextMenuStore.js";
import { viewport } from "./svelte-utils/EditorViewportStore.js";
import BooleanCheckboxComponent from "./BooleanCheckboxComponent.svelte";
export let items;
export let editor;
const LOGGER = CONTEXTMENU_LOGGER;
let submenuItems;
let elementIndex;
let menuHeight = 0, menuWidth = 0;
let top = 0, left = 0;
let submenuHeight = 0, submenuWidth = 0;
let topSub = 0, leftSub = 0;
let itemHeight = 40;
let submenuOpen = false;
export async function show(event, index) {
  elementIndex = index;
  $contextMenuVisible = true;
  submenuOpen = false;
  await tick();
  let posX = event.pageX - $viewport.left;
  let posY = event.pageY - $viewport.top;
  let useMousePosition = true;
  if (!useMousePosition) {
    left = calculatePos($viewport.width, menuWidth, posX);
    top = calculatePos($viewport.height, menuHeight, posY);
  } else {
    left = event.clientX;
    top = event.clientY;
    if (left > $viewport.left + $viewport.width - menuWidth) {
      left = left - menuWidth;
    }
    if (top > $viewport.top + $viewport.height - menuHeight) {
      top = top - menuHeight;
    }
  }
  LOGGER.log("ContextMenu.show:  left=" + left + " top=" + top);
}
export function hide() {
  LOGGER.log("CONTEXTMENU hide");
  $contextMenuVisible = false;
  submenuOpen = false;
}
async function openSub(itemIndex) {
  submenuOpen = true;
  await tick();
  topSub = top + itemHeight + itemIndex * (itemHeight + 2 + 3 + 4);
  leftSub = left + submenuWidth - 20;
  topSub = calculatePos($viewport.width, submenuWidth, topSub);
  leftSub = calculatePos($viewport.height, submenuHeight, leftSub);
}
function getContextMenuDimension(htmlElement) {
  menuHeight = htmlElement.offsetHeight;
  menuWidth = htmlElement.offsetWidth;
}
function getSubMenuDimension(node) {
  submenuHeight = node.offsetHeight;
  submenuWidth = node.offsetWidth;
}
function onClick(event, item, itemIndex) {
  LOGGER.log("CONTEXTMENU onClick");
  submenuOpen = false;
  if (item.hasSubItems()) {
    submenuItems = item.subItems;
    openSub(itemIndex);
  } else {
    item.handler(editor.selectedBox.node, elementIndex, editor);
    hide();
  }
  event.stopPropagation();
  event.preventDefault();
  return false;
}
</script>

<div use:clickOutsideConditional={{ enabled: $contextMenuVisible }} on:click_outside={hide}>
    {#if $contextMenuVisible}
        <nav use:getContextMenuDimension class="contextmenu" style="top: {top}px; left: {left}px">
            {#each items as item, index}
                {#if item.label === "---"}
                    <hr class="contextmenu-hr" />
                {:else}
                    <button class="contextmenu-button" on:click={(event) => onClick(event, item, index)} bind:clientHeight={itemHeight}>
                        {item.label}
                        {#if item.shortcut}
                            <span class="contextmenu-shortcut">{item.shortcut}</span>
                        {/if}
                    </button>
                {/if}
            {/each}
        </nav>
        {#if submenuOpen}
            <nav use:getSubMenuDimension class="contextmenu" style="top: {topSub}px; left: {leftSub}px">
                {#each submenuItems as item, index}
                    {#if item.label === "---"}
                        <hr class="contextmenu-hr" />
                    {:else}
                        <button class="contextmenu-button" on:click={(event) => onClick(event, item, index)}>
                            {item.label}
                            {#if item.shortcut}
                                <span class="contextmenu-shortcut">{item.shortcut}</span>
                            {/if}
                        </button>
                    {/if}
                {/each}
            </nav>
        {/if}
    {/if}
</div>
