<script>import { viewport } from "./svelte-utils/EditorViewportStore.js";
import { Box } from "@freon4dsl/core";
export let box;
export let hasErr = false;
export let parentTop = 0;
export let parentLeft = 0;
let content = [];
let isHovered = false;
let top = 0;
let left = 0;
async function mouseOver(event) {
  if (hasErr) {
    isHovered = true;
    left = event.pageX - $viewport.left - parentLeft + 5;
    top = event.pageY - $viewport.top - parentTop + 5;
    content = box.errorMessages;
  }
}
function mouseMove(event) {
  if (hasErr && isHovered) {
    left = event.pageX - $viewport.left - parentLeft + 5;
    top = event.pageY - $viewport.top - parentTop + 5;
  }
}
function mouseLeave() {
  isHovered = false;
}
function onFocus() {
}
</script>

<span role="group" on:mouseover={mouseOver} on:mouseleave={mouseLeave} on:mousemove={mouseMove} on:focus={onFocus}>
    <slot />
</span>

{#if isHovered}
    <div style="top: {top}px; left: {left}px;" class="error-tooltip">
        {#if content.length > 1}
            <ol class="error-tooltip-list-content">
                {#each content as item}
                    {#if item.length > 0}
                        <li>{item}</li>
                    {/if}
                {/each}
            </ol>
        {:else}
            <span class="error-tooltip-single-content">{content[0]} </span>
        {/if}
    </div>
{/if}
