<svelte:options immutable={true} />

<script>import { LABEL_LOGGER } from "./ComponentLoggers.js";
import { onMount, afterUpdate } from "svelte";
import { LabelBox } from "@freon4dsl/core";
import { componentId } from "./svelte-utils/index.js";
export let box;
const LOGGER = LABEL_LOGGER;
let id = !!box ? componentId(box) : "label-for-unknown-box";
let element = null;
let style;
let cssClass = !!box ? box.cssClass : "";
let text;
onMount(() => {
  if (!!box) {
    box.refreshComponent = refresh;
    cssClass = box.cssClass;
  }
});
afterUpdate(() => {
  if (!!box) {
    box.refreshComponent = refresh;
  }
});
const refresh = (why) => {
  LOGGER.log("REFRESH LabelComponent (" + why + ")");
  if (!!box) {
    text = box.getLabel();
    style = box.cssStyle;
    cssClass = box.cssClass;
  }
};
$: {
  refresh("FROM component " + box?.id);
}
</script>

<span class="label-component {text} {cssClass}" {style} bind:this={element} {id}>
    {@html text}
</span>
