<script>import { GRIDCELL_LOGGER } from "./ComponentLoggers.js";
import { GridBox, isMetaKey, ENTER, FreLogger, GridCellBox, Box } from "@freon4dsl/core";
import { afterUpdate, onMount } from "svelte";
import RenderComponent from "./RenderComponent.svelte";
import { componentId, executeCustomKeyboardShortCut, isOdd } from "./svelte-utils/index.js";
export let grid;
export let cellBox;
export let editor;
const LOGGER = GRIDCELL_LOGGER;
let contentBox;
let id = !!cellBox ? componentId(cellBox) : "gridcell-for-unknown-box";
let row;
let column;
let int = 0;
let orientation = "gridcellNeutral";
let isHeader = "noheader";
let cssStyle = "";
let cssClass = "";
let htmlElement;
function refresh(from) {
  if (!!cellBox) {
    LOGGER.log(
      "REFRESH GridCellComponent " + (!!from ? " from " + from + " " : "") + cellBox?.node?.freLanguageConcept() + "-" + cellBox?.node?.freId()
    );
    LOGGER.log(
      "GridCellComponent row/col " + cellBox.$id + ": " + cellBox.row + "," + cellBox.column + "  span " + cellBox.rowSpan + "," + cellBox.columnSpan + "  box " + cellBox.content.role + "--- " + int++
    );
    contentBox = cellBox.content;
    row = cellBox.row + (cellBox.rowSpan ? " / span " + cellBox.rowSpan : "");
    column = cellBox.column + (cellBox.columnSpan ? " / span " + cellBox.columnSpan : "");
    orientation = grid.orientation === "neutral" ? "gridcellNeutral" : grid.orientation === "row" ? isOdd(cellBox.row) ? "gridcellOdd" : "gridcellEven" : isOdd(cellBox.column) ? "gridcellOdd" : "gridcellEven";
    if (cellBox.isHeader) {
      isHeader = "gridcell-header";
    }
    cssStyle = contentBox.cssStyle;
    cssClass = cellBox.cssClass;
  }
}
async function setFocus() {
  htmlElement.focus();
}
onMount(() => {
  cellBox.refreshComponent = refresh;
  cellBox.setFocus = setFocus;
});
afterUpdate(() => {
  cellBox.refreshComponent = refresh;
  cellBox.setFocus = setFocus;
});
const onKeydown = (event) => {
  LOGGER.log("GridCellComponent onKeyDown");
  if (isMetaKey(event) || event.key === ENTER) {
    LOGGER.log("Keyboard shortcut in GridCell ===============");
    const index = cellBox.propertyIndex;
    executeCustomKeyboardShortCut(event, index, cellBox, editor);
  }
};
$: {
  refresh(cellBox?.id);
}
</script>

<div
    class="grid-cell-component {orientation} {isHeader} {cssClass}"
    style:grid-row={row}
    style:grid-column={column}
    style={cssStyle}
    on:keydown={onKeydown}
    {id}
    bind:this={htmlElement}
    role="gridcell"
>
    <RenderComponent box={contentBox} {editor} />
</div>
