<script>import { isNumber } from "lodash";
import TextComponent from "./TextComponent.svelte";
import DropdownComponent from "./DropdownComponent.svelte";
import { clickOutsideConditional, componentId, selectedBoxes } from "./svelte-utils/index.js";
import {
  ARROW_DOWN,
  ARROW_UP,
  ENTER,
  ESCAPE,
  isSelectBox,
  FreEditor,
  FreLogger,
  Box,
  TextBox,
  isRegExp,
  triggerTypeToString,
  isActionBox,
  FreCaretPosition,
  FreCaret
} from "@freon4dsl/core";
import RenderComponent from "./RenderComponent.svelte";
import { Button } from "flowbite-svelte";
import { FontAwesomeIcon } from "@fortawesome/svelte-fontawesome";
import { faGripVertical, faEllipsis, faXmark, faCaretRight, faCaretDown, faShareNodes, faSquareArrowUpRight, faLinkSlash } from "@fortawesome/free-solid-svg-icons";
import { runInAction } from "mobx";
import { afterUpdate, onMount } from "svelte";
const LOGGER = new FreLogger("ItemGroupComponent2");
export let box;
export let editor;
let textBox;
$: textBox = box?.textBox;
let id;
id = !!box ? componentId(box) : "itemgroup2-with-unknown-box";
let isEditing = false;
let dropdownShown = false;
let text = "";
let selectedId;
let filteredOptions;
let allOptions;
let textComponent;
let cssClass = "";
let style;
let contentElement = null;
let label;
let child;
let isExpanded = false;
let contentStyle = "display: none";
let isDraggable = true;
let canDelete = false;
let canUnlink = false;
let canEdit = true;
let canExpand = true;
let setText = (value) => {
  if (value === null || value === void 0) {
    text = "";
  } else {
    text = value;
  }
};
const noOptionsId = "noOptions";
let getOptions = () => {
  let result = box?.getOptions(editor);
  if (result === null || result === void 0) {
    result = [{ id: noOptionsId, label: "<no known options>" }];
  }
  return result;
};
const setFocus = () => {
  if (!!textComponent) {
    textComponent.setFocus();
  } else {
    console.error("TextDropdownComponent2 " + id + " has no textComponent");
  }
};
const refresh = (why) => {
  if (isSelectBox(box)) {
  }
  cssClass = box.cssClass;
  label = box.getLabel();
  child = box?.child;
  canDelete = box.canDelete;
  canUnlink = box.canUnlink;
  canExpand = box.canExpand;
};
afterUpdate(() => {
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
  box.triggerKeyPressEvent = triggerKeyPressEvent;
});
onMount(() => {
  box.setFocus = setFocus;
  box.refreshComponent = refresh;
  box.triggerKeyPressEvent = triggerKeyPressEvent;
});
const triggerKeyPressEvent = (key) => {
  textUpdateFunction({ content: key, caret: 1 });
  box.textHelper.setText(key);
};
const textUpdateFunction = (data) => {
  LOGGER.log(`textUpdateFunction for ${box.kind}: ` + JSON.stringify(data));
  dropdownShown = true;
  allOptions = getOptions();
  filteredOptions = allOptions.filter((o) => o.label.startsWith(data.content));
  makeUnique();
  LOGGER.log(`FilteredOptions are ${filteredOptions.map((o) => o.label)}`);
  return false;
};
const textUpdate = (event) => {
  LOGGER.log(`textUpdate for ${box.kind}: ` + JSON.stringify(event.detail));
  dropdownShown = true;
  allOptions = getOptions();
  filteredOptions = allOptions.filter((o) => o.label.startsWith(text));
  makeUnique();
};
function makeUnique() {
  const seen = [];
  const result = [];
  filteredOptions.forEach((option) => {
    if (seen.includes(option.label)) {
      LOGGER.log("Option " + JSON.stringify(option) + " is a duplicate");
    } else {
      seen.push(option.label);
      result.push(option);
    }
  });
  filteredOptions = result;
}
function selectLastOption() {
  if (dropdownShown) {
    if (filteredOptions?.length !== 0) {
      selectedId = filteredOptions[filteredOptions.length - 1].id;
    } else {
      editor.setUserMessage("no valid selection");
    }
  }
}
function selectFirstOption() {
  if (dropdownShown) {
    if (filteredOptions?.length !== 0) {
      selectedId = filteredOptions[0].id;
    } else {
      editor.setUserMessage("No valid selection");
    }
  }
}
const onKeyDown = (event) => {
  LOGGER.log("onKeyDown: " + id + " [" + event.key + "] alt [" + event.altKey + "] shift [" + event.shiftKey + "] ctrl [" + event.ctrlKey + "] meta [" + event.metaKey + "], selectedId: " + selectedId + " dropdown:" + dropdownShown + " editing:" + isEditing);
  if (dropdownShown) {
    if (!event.ctrlKey && !event.altKey) {
      switch (event.key) {
        case ESCAPE: {
          dropdownShown = false;
          event.preventDefault();
          event.stopPropagation();
          break;
        }
        case ARROW_DOWN: {
          if (dropdownShown) {
            if (!selectedId || selectedId.length == 0) {
              selectFirstOption();
            } else {
              const index = filteredOptions.findIndex((o) => o.id === selectedId);
              if (index + 1 < filteredOptions.length) {
                selectedId = filteredOptions[index + 1].id;
              } else if (index + 1 === filteredOptions.length) {
                selectFirstOption();
              }
            }
            event.preventDefault();
            event.stopPropagation();
          }
          break;
        }
        case ARROW_UP: {
          if (dropdownShown) {
            if (!selectedId || selectedId.length == 0) {
              selectLastOption();
            } else {
              const index = filteredOptions.findIndex((o) => o.id === selectedId);
              if (index > 0) {
                selectedId = filteredOptions[index - 1].id;
              } else if (index === 0) {
                selectLastOption();
              }
            }
            event.preventDefault();
            event.stopPropagation();
          }
          break;
        }
        case ENTER: {
          let chosenOption = null;
          if (filteredOptions.length <= 1) {
            if (filteredOptions.length !== 0) {
              chosenOption = filteredOptions[0];
            } else {
              editor.setUserMessage("No valid selection");
            }
          } else {
            const index = filteredOptions.findIndex((o) => o.id === selectedId);
            if (index >= 0 && index < filteredOptions.length) {
              chosenOption = filteredOptions[index];
            }
          }
          if (!!chosenOption) {
            storeAndExecute(chosenOption);
          } else {
            setText(textBox.getText());
            isEditing = false;
            dropdownShown = false;
          }
          event.preventDefault();
          event.stopPropagation();
          break;
        }
        default: {
          isEditing = false;
          dropdownShown = false;
        }
      }
    }
  } else {
    if (!event.ctrlKey && !event.altKey) {
      switch (event.key) {
        case ENTER: {
          startEditing();
          event.stopPropagation();
          event.preventDefault();
        }
      }
    }
  }
};
function clearText() {
  LOGGER.log(`clearText for ${id} from text '${text}' & boxtext '${box.textHelper.getText()}' `);
  box.textHelper.setText("");
}
const itemSelected = () => {
  LOGGER.log("itemSelected " + selectedId);
  const index = filteredOptions.findIndex((o) => o.id === selectedId);
  if (index >= 0 && index < filteredOptions.length) {
    const chosenOption = filteredOptions[index];
    if (!!chosenOption) {
      storeAndExecute(chosenOption);
    }
  }
  isEditing = false;
  dropdownShown = false;
};
const startEditing = (event) => {
  LOGGER.log("TextDropdownComponent: startEditing" + JSON.stringify(event?.detail));
  isEditing = true;
  dropdownShown = true;
  editor.selectElementForBox(box);
  allOptions = getOptions();
  if (!!event) {
    if (text === void 0 || text === null) {
      filteredOptions = allOptions.filter((o) => true);
    } else {
      filteredOptions = allOptions.filter((o) => {
        return o?.label?.startsWith(text);
      });
    }
  } else {
    filteredOptions = allOptions.filter((o) => o?.label?.startsWith(text.substring(0, 0)));
  }
  makeUnique();
};
function storeAndExecute(selected) {
  LOGGER.log("executing option " + selected.label);
  isEditing = false;
  dropdownShown = false;
  if (isActionBox(box)) {
    clearText();
  }
  runInAction(() => {
    box.selectOption(editor, selected);
    setText(selected.label);
  });
}
const endEditing = () => {
  LOGGER.log("endEditing " + id + " dropdownShow:" + dropdownShown + " isEditing: " + isEditing);
  if (isEditing === true) {
    isEditing = false;
  } else {
    if (dropdownShown === true) {
      dropdownShown = false;
    }
    return;
  }
  if (dropdownShown) {
    allOptions = getOptions();
    let validOption = allOptions.find((o) => o.label === text);
    if (!!validOption && validOption.id !== noOptionsId) {
      storeAndExecute(validOption);
    } else {
      setText(textBox.getText());
    }
    dropdownShown = false;
  }
};
const onBlur = () => {
  LOGGER.log("onBlur " + id);
  if (!document.hasFocus() || !$selectedBoxes.includes(box)) {
    endEditing();
  }
};
const onFocusOutText = () => {
  LOGGER.log(`onFocusOutText ${id} text '${text}'`);
  if (isEditing) {
    isEditing = false;
  }
};
const onClickOutside = () => {
  LOGGER.log("onClickOutside");
  endEditing();
};
refresh();
const selectItem = (event) => {
  editor.selectElementForBox(box);
  event.preventDefault();
  event.stopPropagation();
};
function toggleExpanded() {
  contentElement.style.display = contentElement.style.display === "block" ? "none" : "block";
  isExpanded = !isExpanded;
  contentStyle = isExpanded ? "display:block;" : "display:none;";
}
function shareItem() {
  box.executeAction(editor, "make-shareable");
}
function deleteItem() {
  box.executeAction(editor, "delete");
}
function onTextKeyDown(event) {
  const keyboardEvent = event;
  onKeyDown(keyboardEvent);
}
</script>


<!-- svelte-ignore a11y-no-noninteractive-element-interactions a11y-click-events-have-key-events a11y-interactive-supports-focus -->
<div id="{id}-group" class="item-group {cssClass} w-full" style="{style}" on:click={selectItem} role="button">
	{#key isDraggable}
		<FontAwesomeIcon class="w-3 h-3 ml-1 drag-button" style="cursor: grab;" icon={faGripVertical} />
	{/key}
	{#key isExpanded}
		{#if canExpand}
			<Button pill={true} class="w-4 h-7 p-0 ml-1 toggle-button" color="none" size="xs" on:click={toggleExpanded}>
				<FontAwesomeIcon class="w-3 h-3" icon={isExpanded ? faCaretDown : faCaretRight} />
			</Button>
		{:else}
			<span class="w-5" />
		{/if}
	{/key}
  <span class="item-group-label">{label}</span>

<span id="{id}"
      use:clickOutsideConditional={{enabled: dropdownShown}}
      on:click_outside={onClickOutside}
      on:blur={onBlur}
      on:contextmenu={(event) => endEditing()}
      class="text-dropdown-component"
      role="none"
>
    <TextComponent
      bind:isEditing={isEditing}
      bind:text={text}
      bind:this={textComponent}
      partOfActionBox={true}
      box={textBox}
      editor={editor}
      textUpdateFunction={textUpdateFunction}
      endEditingParentFunction={endEditing}
      on:keydown={onTextKeyDown}
      on:startEditing={startEditing}
      on:endEditing={endEditing}
      on:onFocusOutText={onFocusOutText}
    />
    {#if dropdownShown}
        <DropdownComponent
                bind:selectedId={selectedId}
                bind:options={filteredOptions}
                on:freItemSelected={itemSelected}/>
    {/if}
</span>
{#if canUnlink}
<Button pill={true} size="xs" class="w-7 h-7 p-0 action-button" outline on:click="{shareItem}">
    <FontAwesomeIcon class="w-3 h-3" icon={faLinkSlash} />
</Button>
{/if}
{#if canDelete}
<Button pill={true} size="xs" class="w-7 h-7 p-0 action-button" outline on:click={deleteItem} >
    <FontAwesomeIcon class="w-3 h-3" icon={faXmark} />
</Button> 
{/if}
</div>
{#key contentStyle}
    <div bind:this={contentElement} style="{contentStyle}">
        <RenderComponent box={child} editor={editor}/>
    </div>
{/key}
